def validate(rows):
    """Check every row's qty. Bad rows get a note naming the row, then ALL are raised together."""
    errors = []
    for i, row in enumerate(rows):
        if row["qty"] <= 0:
            err = ValueError("qty must be positive")
            err.add_note(f"row {i}: sku={row['sku']}")
            errors.append(err)
    if errors:
        raise ExceptionGroup("invalid rows", errors)

rows = [{"sku": "A1", "qty": 2}, {"sku": "B7", "qty": 0}, {"sku": "C3", "qty": -1}]
try:
    validate(rows)
except ExceptionGroup as eg:
    for err in eg.exceptions:
        print(err, err.__notes__)
